const sizes = [1,2,3];
const top = 8;
const banned = -1;
const climb = (position) => {
  if (position === top) return 1;
  let count = 0;
  for (const s of sizes) {
    const next = position + s;
    if (next <= top && next !== banned) count += climb(next);
  }
  return count;
};
return climb(0);
